int sum_digits(int n) {
    if (n < 10) return n;
    return n % 10 + sum_digits(n / 10);
}

int sum_digits(int n) {
    if (n == 0) return 0;
    return n % 10 + sum_digits(n / 10);
}

int sum_digits(int n) {
    if (n < 10) return n;
    int rest = sum_digits(n / 10);
    return rest + n % 10;
}
